const games=[{id:'orbit',title:'Orbit Breaker',studio:'Satellite Arcade',genre:'Arcade',color:'#d5ff5f',description:'One ship. A sky full of trouble. How long can you hold your orbit?',tags:'Space shooter · 30-second demo',instruction:'Drag to steer. Your ship fires automatically.',kind:0},{id:'neon',title:'Neon Drift',studio:'Afterhours Games',genre:'Arcade',color:'#bca4ff',description:'Find your lane. Chase the glow. Leave the ordinary behind.',tags:'Endless racer · 30-second demo',instruction:'Tap the left or right side to change lanes.',kind:1},{id:'prism',title:'Prism Pop',studio:'Little Loop Studio',genre:'Puzzle',color:'#66e0e1',description:'A small puzzle with a satisfying pop. Catch the color, keep the streak.',tags:'Color puzzle · 30-second demo',instruction:'Tap the glowing color. Match as many tiles as you can.',kind:2}];
