function escapeHTML(value){return String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function makeCard(g){const el=document.createElement('article');el.className='game-card';el.dataset.id=g.id;el.innerHTML=`<canvas width="480" height="760" aria-label="${escapeHTML(g.title)} playable demo"></canvas><div class="shade"></div><div class="card-top"><span class="pill">${g.genre.toUpperCase()} / ${String(g.kind+1).padStart(2,'0')}</span><span class="demo-label">✦ Playable demo</span></div><div class="score"></div><div class="instruction"></div><div class="game-info"><div class="studio-name"><span class="studio-avatar">${g.studio[0]}</span>${escapeHTML(g.studio)}</div><h2>${escapeHTML(g.title)}</h2><p>${escapeHTML(g.description)}</p><div class="tags">${escapeHTML(g.tags)}</div><button class="primary play">▶ Play now</button><button class="secondary info">About game</button></div><div class="actions"><button class="action save" aria-label="Save ${escapeHTML(g.title)}" aria-pressed="false"><span>♡</span><small>Save</small></button><button class="action next" aria-label="Next game"><span>↓</span><small>Next</small></button></div>`;const canvas=el.querySelector('canvas'),ctx=canvas.getContext('2d');const c={g,el,canvas,ctx,state:null};cards.set(g.id,c);el.querySelector('.play').onclick=()=>active===c?stop():start(g.id);el.querySelector('.save').onclick=()=>save(g.id);el.querySelector('.info').onclick=()=>details(g.id);el.querySelector('.next').onclick=next;canvas.addEventListener('pointerdown',e=>{if(active!==c)return;canvas.setPointerCapture(e.pointerId);pointer(c,e,true)});canvas.addEventListener('pointermove',e=>{if(active===c&&e.buttons)pointer(c,e,false)});return el}
