function show(v){stop();view=v;document.querySelectorAll('.view').forEach(e=>e.classList.add('hidden'));$('#'+v+'-view').classList.remove('hidden');document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view===v));if(v==='studio')renderStats();if(v==='saved')renderSaved()}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>show(b.dataset.view));document.querySelector('.brand').onclick=e=>{e.preventDefault();show('feed')};document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{stop();filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('selected',x===b));cards.forEach(c=>c.el.classList.toggle('hidden',filter!=='All'&&c.g.genre!==filter));feed.scrollTop=0});
function visibleCards(){return [...cards.values()].filter(c=>!c.el.classList.contains('hidden'))}function current(){const cs=visibleCards();return cs.reduce((a,c)=>Math.abs(c.el.offsetTop-feed.offsetTop-feed.scrollTop)<Math.abs(a.el.offsetTop-feed.offsetTop-feed.scrollTop)?c:a,cs[0])}function next(){stop();const cs=visibleCards(),i=cs.indexOf(current());cs[(i+1)%cs.length].el.scrollIntoView({behavior:'smooth',block:'start'})}feed.addEventListener('scroll',()=>{if(active&&current()!==active)stop()},{passive:true});feed.addEventListener('keydown',e=>{if(active||e.target.matches('input,textarea,select'))return;if(e.key==='ArrowDown'){e.preventDefault();next()}if(e.key==='ArrowUp'){e.preventDefault();const cs=visibleCards(),i=cs.indexOf(current());cs[(i+cs.length-1)%cs.length].el.scrollIntoView({behavior:'smooth',block:'start'})}});
function start(id){stop();const c=cards.get(id);if(!c)throw Error('Unknown game');if(view!=='feed')show('feed');if(c.el.classList.contains('hidden')){filter='All';document.querySelector('[data-filter="All"]').click()}c.el.scrollIntoView({block:'start'});active=c;if(c.g.upload){startUpload(c);return}c.state={elapsed:0,score:0,x:240,lane:1,objects:[],bullets:[],spawn:0,shot:0,target:Math.floor(Math.random()*4),tiles:Array.from({length:12},()=>Math.floor(Math.random()*4))};c.el.classList.add('playing');c.el.querySelector('.play').textContent='Pause demo';c.el.querySelector('.instruction').textContent=c.g.instruction;c.el.querySelector('.end-screen')?.remove();stats[id].starts++;feed.focus({preventScroll:true})}
function stop(){if(!active)return;active.el.querySelector('.upload-player')?.remove();active.el.classList.remove('playing');active.el.querySelector('.play').textContent='▶ Play again';active.el.querySelector('.instruction').textContent='';active.el.querySelector('.score').textContent='';active=null}
function end(){const c=active,score=c.state.score;stop();const panel=document.createElement('div');panel.className='end-screen';const h=document.createElement('h3');h.textContent='Good game.';const p=document.createElement('p');p.textContent=`${score} points · One more round?`;const b=document.createElement('button');b.className='primary';b.textContent='Play again';b.onclick=()=>start(c.g.id);panel.append(h,p,b);c.el.append(panel)}
function pointer(c,e,down){if(c.g.upload)return;const rect=c.canvas.getBoundingClientRect(),x=(e.clientX-rect.left)/rect.width*480,y=(e.clientY-rect.top)/rect.height*760,s=c.state;if(c.g.kind===0)s.x=Math.max(25,Math.min(455,x));if(c.g.kind===1&&down)s.lane=Math.min(2,Math.max(0,s.lane+(x<240?-1:1)));if(c.g.kind===2&&down){const col=Math.floor((x-60)/120),row=Math.floor((y-230)/112);if(col<0||col>2||row<0||row>3)return;const n=row*3+col;if(s.tiles[n]===s.target){s.score+=10;s.target=Math.floor(Math.random()*4);s.tiles=Array.from({length:12},()=>Math.floor(Math.random()*4));s.tiles[Math.floor(Math.random()*12)]=s.target}else s.score=Math.max(0,s.score-5)}}
window.addEventListener('keydown',e=>{if(!active||active.g.upload||e.target.matches('input,select,textarea'))return;if(['ArrowLeft','ArrowRight','Escape',' '].includes(e.key))e.preventDefault();const s=active.state;if(e.key==='Escape'||e.key===' ')stop();else if(e.key==='ArrowLeft'){s.x=Math.max(25,s.x-30);s.lane=Math.max(0,s.lane-1)}else if(e.key==='ArrowRight'){s.x=Math.min(455,s.x+30);s.lane=Math.min(2,s.lane+1)}else if(active.g.kind===2&&/^[1-9]$/.test(e.key)){let i=Number(e.key)-1;if(s.tiles[i]===s.target){s.score+=10;s.target=(s.target+1)%4;s.tiles[i]=s.target}}});document.addEventListener('visibilitychange',()=>{if(document.hidden)stop()});
const colors=['#d5ff5f','#a797ff','#67dfed','#ff916d'];function rect(ctx,x,y,w,h,color,r=8){ctx.fillStyle=color;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill()}function ship(ctx,x,y,color){ctx.fillStyle=color;ctx.beginPath();ctx.moveTo(x,y-25);ctx.lineTo(x+19,y+21);ctx.lineTo(x,y+10);ctx.lineTo(x-19,y+21);ctx.closePath();ctx.fill();rect(ctx,x-5,y+23,10,18,'#fff8',3)}
function draw(c,dt){const {ctx,g}=c,s=active===c?c.state:null;const grd=ctx.createLinearGradient(0,0,480,760);grd.addColorStop(0,g.kind===1?'#191331':'#0b1721');grd.addColorStop(1,g.kind===2?'#152e32':'#102c36');ctx.fillStyle=grd;ctx.fillRect(0,0,480,760);if(g.kind===0){for(let i=0;i<75;i++){const x=(i*137.7)%480,y=(i*93.2+time*(s?50:12))%760;ctx.fillStyle=i%4?'#8cb6c655':'#e0f7ff';ctx.fillRect(x,y,i%4?1:2,2)}if(!s){ctx.strokeStyle='#4d797c45';for(let r=80;r<300;r+=70){ctx.beginPath();ctx.arc(240,340,r,0,Math.PI*2);ctx.stroke()}ship(ctx,240+Math.sin(time)*45,385,g.color);for(let i=0;i<5;i++)rect(ctx,55+i*78,180+Math.sin(time+i)*30,25,25,'#ff916daa')}else{ship(ctx,s.x,610,g.color);s.spawn+=dt;s.shot+=dt;if(s.spawn>.55){s.objects.push({x:25+Math.random()*430,y:100});s.spawn=0}if(s.shot>.16){s.bullets.push({x:s.x,y:585});s.shot=0}s.bullets.forEach(b=>{b.y-=dt*530;rect(ctx,b.x-2,b.y,4,17,g.color,2)});s.objects.forEach(o=>{o.y+=dt*140;rect(ctx,o.x-14,o.y-14,28,28,'#ff916d',5);const b=s.bullets.find(b=>Math.abs(b.x-o.x)<20&&Math.abs(b.y-o.y)<25);if(b){o.y=850;b.y=-100;s.score+=10}if(Math.abs(o.x-s.x)<27&&Math.abs(o.y-610)<30){o.y=850;s.score=Math.max(0,s.score-10)}});s.objects=s.objects.filter(o=>o.y<800);s.bullets=s.bullets.filter(b=>b.y>-30)}}if(g.kind===1){ctx.fillStyle='#141622';ctx.fillRect(55,0,370,760);ctx.strokeStyle='#bca4ff';ctx.lineWidth=2;[55,425].forEach(x=>{ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,760);ctx.stroke()});ctx.strokeStyle='#bca4ff35';ctx.setLineDash([40,30]);ctx.lineDashOffset=-time*(s?190:60);[178,302].forEach(x=>{ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,760);ctx.stroke()});ctx.setLineDash([]);for(let i=0;i<12;i++){const y=(i*83+time*60)%760;rect(ctx,20,y,12,25,'#bca4ff55',2);rect(ctx,449,y,12,25,'#67dfed55',2)}const x=116+(s?s.lane:1)*124;rect(ctx,x-21,560,42,75,g.color,9);rect(ctx,x-14,572,28,18,'#192139',4);rect(ctx,x-16,628,32,4,'#fff',2);if(s){s.spawn+=dt;if(s.spawn>.7){s.objects.push({lane:Math.floor(Math.random()*3),y:70});s.spawn=0}s.objects.forEach(o=>{o.y+=dt*250;rect(ctx,116+o.lane*124-20,o.y,40,60,'#ff916d',8);if(o.y>635&&!o.counted){s.score+=10;o.counted=true}if(o.lane===s.lane&&o.y>510&&o.y<635){s.score=Math.max(0,s.score-15);o.y=850}});s.objects=s.objects.filter(o=>o.y<800)}}if(g.kind===2){const target=s?s.target:Math.floor(time/3)%4;rect(ctx,181,155,118,44,colors[target],22);ctx.fillStyle='#14222b';ctx.font='bold 15px sans-serif';ctx.textAlign='center';ctx.fillText('MATCH THIS',240,183);for(let i=0;i<12;i++){const color=s?s.tiles[i]:i%4;const x=60+(i%3)*120,y=230+Math.floor(i/3)*112;rect(ctx,x+4,y+4,100,92,colors[color],18);ctx.fillStyle='#ffffff55';ctx.beginPath();ctx.arc(x+54,y+49,17,0,Math.PI*2);ctx.fill()}}if(s){s.elapsed+=dt;stats[g.id].seconds+=dt;c.el.querySelector('.score').textContent=`${String(s.score).padStart(3,'0')}  /  ${Math.max(0,Math.ceil(30-s.elapsed))}s`;if(s.elapsed>=30)end()}}
function animate(now){const dt=Math.min((now-last)/1000,.05);last=now;time+=dt;if(view==='feed'&&!document.hidden){const c=current();if(c&&!c.g.upload)draw(c,dt);else if(c&&active===c&&c.g.upload)stats[c.g.id].seconds+=dt}requestAnimationFrame(animate)}requestAnimationFrame(animate);
function details(id){const g=games.find(g=>g.id===id);stats[id].details++;const box=$('#details-content');box.replaceChildren();const label=document.createElement('span');label.className='overline';label.textContent=g.studio;const h=document.createElement('h2');h.textContent=g.title;const p=document.createElement('p');p.textContent=g.description;const note=document.createElement('p');note.textContent=g.upload?'Uploaded by '+g.studio+'. This demo is available inside the QuickPlay feed.':'This is an original QuickPlay concept demo. A full-game link will appear here when a real studio connects its release.';const b=document.createElement('button');b.className='primary';b.textContent=saved.has(id)?'Remove from saved':'Save game';b.onclick=()=>{save(id);$('#details').close()};box.append(label,h,p,note,b);$('#details').showModal()}$('#close-details').onclick=()=>$('#details').close();$('#details').onclick=e=>{if(e.target===$('#details'))$('#details').close()};
